"""Carmen-approved BBLO advertising menu, approved November 9, 2026."""
from html import escape
from urllib.parse import quote

INTRO_END = '2027-02-07T00:00:00-05:00'
OFFERS = [
 ('Featured Directory', '$15/month or $150 for 12 months', '$20/month or $200 for 12 months', 'Add a Sponsored card after TLC, BBLO, Media Minds and MJ Photography, ahead of the remaining alphabetical listings, with a link to your included member profile. Limited to six paid cards; order within the featured section rotates monthly.', 'Request directory availability'),
 ('Homepage Spotlight', '$50/month', '$75/month', 'One Sponsored feature directly below the TLC homepage hero, with a supplied image, up to 50 words and a link to your member profile. One advertiser at a time. Book one to three consecutive months, subject to availability.', 'Request homepage dates'),
 ('Sponsored Business Story', '$225 once', '$300 once', 'A separately written 500–700-word Sponsored feature built from your approved information and up to three original photos you supply. Includes one consolidated revision, profile and business links, and 12 months online. Homepage placement is purchased separately. Limited to two new stories per month.', 'Request a business story'),
]

def cards():
    items=[]
    for title,intro,standard,copy,cta in OFFERS:
        url='mailto:carmen@doitwithtlc.com?subject='+quote('BBLO advertising: '+title)+'&body='+quote('My name:\nBusiness:\nPlacement: '+title+'\nPreferred dates:\nPhone:\n\nPlease confirm availability, scope, terms and payment instructions.\n')
        items.append('<article class="card bblo-ad-card"><p class="eyebrow">Optional Sponsored advertising</p><h3>'+title+'</h3><p class="bblo-ad-intro" data-ad-intro data-intro-end="'+INTRO_END+'"><strong>Introductory: '+intro+'</strong></p><p class="bblo-ad-standard"><strong>Standard: '+standard+'</strong></p><p>'+copy+'</p><a class="button secondary" href="'+escape(url,quote=True)+'">'+cta+'</a></article>')
    return '<div class="bblo-ad-rate-grid">'+''.join(items)+'</div>'

def note():
    return '<p class="bblo-ad-window" data-ad-intro data-intro-end="'+INTRO_END+'"><strong>Introductory bookings: November 9, 2026–February 6, 2027.</strong> First bookings must be paid within this window: up to 12 months for directory placement, up to three months for homepage placement, and one story per business. Renewals use the then-approved published rate.</p><p class="note">Available to active, approved BBLO members. Your public profile, standard directory listing and scheduled member spotlight opportunities remain included with membership. Advertising is separate from dues for every membership plan. Annual directory payment saves two months compared with twelve monthly advertising payments. Dates, availability, scope and terms are confirmed in writing before payment. Paid placements are labeled Sponsored; no minimum views, leads, sales or search rankings are promised.</p>'

def terms():
    return '<div class="bblo-ad-terms"><h2>What your booking includes</h2><details><summary>Materials, production and approvals</summary><p>Directory placement uses your supplied logo or photo, a short description and one profile link; one factual or image update per quarter is included. Homepage placement includes template formatting and one consolidated revision, with one creative per booked month.</p><p>Stories use your completed written questionnaire and approved facts, in one language. Translation, interviews, photography, video, extra revisions and substantial rewrites require a separate written quote. Stories link from the member profile and a sponsored-story index. Social posts, email distribution, paid media and event recognition are additional services.</p><p>Allow five business days for directory or homepage setup after payment and complete materials. Allow ten business days for a story draft, followed by your approval. Confirm actual live dates before booking; the placement or hosting term begins on its agreed live date.</p></details><details><summary>Booking periods and renewals</summary><p>One business per booking. Annual dual membership does not automatically provide two advertising placements. Monthly placements use calendar months; annual directory placement runs 12 months from the agreed start. No category exclusivity or permanent first position is included.</p><p>We confirm each renewal separately; there is no automatic renewal. A story includes 12 months online. Hosting-only renewal is $50 for another 12 months, including one factual correction of up to 15 minutes; a rewrite or new promotional placement is quoted separately. Annual homepage bookings are not offered at launch.</p></details><details><summary>Cancellations and missed delivery</summary><p>Unstarted placement periods are refundable. Once a monthly period begins, there is no partial-month refund. For annual directory cancellation, delivered months are deducted at the booked monthly rate and the unused balance is refunded. Unearned story-production fees are refundable before publication; no refund follows approved publication. Missed delivery caused by TLC downtime is extended or credited.</p></details><p>Request buttons prepare an email in your email app. Review and send your inquiry; no payment is collected on this page. Send only approved business materials and images you have permission to share.</p></div>'

